PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS properties(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, client TEXT NOT NULL, address TEXT NOT NULL, locality TEXT, asset_class TEXT, title_reference TEXT, data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_maps(tenant TEXT NOT NULL, system TEXT NOT NULL, source_id TEXT NOT NULL, property_id TEXT NOT NULL REFERENCES properties(id), method TEXT NOT NULL, reviewer TEXT NOT NULL, PRIMARY KEY(tenant,system,source_id));
CREATE TABLE IF NOT EXISTS raw_records(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, client TEXT NOT NULL, system TEXT NOT NULL, source_id TEXT NOT NULL, version TEXT NOT NULL, hash TEXT NOT NULL, payload TEXT NOT NULL, observed_at TEXT NOT NULL, effective_at TEXT, deleted INTEGER NOT NULL DEFAULT 0, UNIQUE(tenant,system,source_id,hash));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, client TEXT NOT NULL, raw_id TEXT NOT NULL REFERENCES raw_records(id), hash TEXT NOT NULL, name TEXT NOT NULL, pages TEXT NOT NULL, model TEXT NOT NULL, source_uri TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, client TEXT NOT NULL, property_id TEXT REFERENCES properties(id), raw_id TEXT NOT NULL REFERENCES raw_records(id), document_id TEXT REFERENCES documents(id), page INTEGER, kind TEXT NOT NULL, measure TEXT NOT NULL, value REAL, unit TEXT NOT NULL, basis TEXT NOT NULL, transaction_status TEXT NOT NULL, source_class TEXT NOT NULL, confidence REAL NOT NULL, status TEXT NOT NULL, issues TEXT NOT NULL, data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, UNIQUE(raw_id,measure,page));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, client TEXT NOT NULL, evidence_id TEXT REFERENCES evidence(id), raw_id TEXT REFERENCES raw_records(id), type TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL, reviewer TEXT, reason TEXT, decided_at TEXT);
CREATE TABLE IF NOT EXISTS entities(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, client TEXT NOT NULL, property_id TEXT NOT NULL REFERENCES properties(id), raw_id TEXT NOT NULL REFERENCES raw_records(id), type TEXT NOT NULL, source_id TEXT NOT NULL, effective_at TEXT, data TEXT NOT NULL, UNIQUE(raw_id,type,source_id));
CREATE TABLE IF NOT EXISTS property_links(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, property_id TEXT NOT NULL REFERENCES properties(id), entity_id TEXT NOT NULL REFERENCES entities(id), relation TEXT NOT NULL, valid_from TEXT, valid_to TEXT);
CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, client TEXT NOT NULL, property_id TEXT NOT NULL REFERENCES properties(id), status TEXT NOT NULL, data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, approved_by TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS connectors(tenant TEXT NOT NULL, system TEXT NOT NULL, paused INTEGER NOT NULL DEFAULT 0, cursor TEXT, last_success TEXT, last_error TEXT, imported INTEGER NOT NULL DEFAULT 0, config TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(tenant,system));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, system TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt TEXT, error TEXT, created_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE IF NOT EXISTS secrets(tenant TEXT NOT NULL, name TEXT NOT NULL, encrypted TEXT NOT NULL, PRIMARY KEY(tenant,name));
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, detail TEXT NOT NULL, at TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS merges(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, snapshot TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, reversed_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS evidence_scope ON evidence(tenant,client,status,property_id);
CREATE INDEX IF NOT EXISTS raw_source ON raw_records(tenant,system,source_id);
CREATE INDEX IF NOT EXISTS review_scope ON reviews(tenant,client,status);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END;
INSERT OR IGNORE INTO schema_version VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
